import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const BlackjackPage = ({ socket, setBalance }) => {
  const { user } = useAuth();
  const [gameState, setGameState] = useState('waiting'); // waiting, betting, in_progress, completed
  const [betAmount, setBetAmount] = useState(100);
  const [balance, setLocalBalance] = useState(user?.balance || 0);
  const [message, setMessage] = useState('');
  const [playerHand, setPlayerHand] = useState([]);
  const [dealerHand, setDealerHand] = useState([]);
  const [currentGame, setCurrentGame] = useState(null);
  const [playerValue, setPlayerValue] = useState(0);
  const [dealerValue, setDealerValue] = useState(0);
  const [result, setResult] = useState('');
  const [showFinalResult, setShowFinalResult] = useState(false);

  // Update local balance when user balance changes
  useEffect(() => {
    if (user) {
      setLocalBalance(user.balance);
    }
  }, [user]);

  const calculateHandValue = (hand) => {
    if (!hand) return 0;

    let value = 0;
    let aces = 0;

    for (const card of hand) {
      if (card.rank === 'A') {
        aces++;
        value += 11;
      } else if (['J', 'Q', 'K'].includes(card.rank)) {
        value += 10;
      } else {
        value += parseInt(card.rank);
      }
    }

    // Adjust for aces if value is over 21
    while (value > 21 && aces > 0) {
      value -= 10; // Convert ace from 11 to 1
      aces--;
    }

    return value;
  };

  const startGame = async () => {
    if (betAmount > balance) {
      setMessage('Insufficient balance');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/blackjack/start`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ betAmount })
      });

      const data = await response.json();

      if (response.ok) {
        setGameState('in_progress');
        setCurrentGame(data.gameId || null);

        // Set initial hands and values
        if (data.playerHand) setPlayerHand(data.playerHand);
        if (data.dealerHand) setDealerHand(data.dealerHand);

        // Calculate and set values
        const playerValue = calculateHandValue(data.playerHand);
        const dealerValue = calculateHandValue(data.dealerHand);
        setPlayerValue(playerValue);
        setDealerValue(dealerValue);

        setMessage('');

        // Update balance
        setLocalBalance(prev => prev - betAmount);
        setShowFinalResult(false);
      } else {
        setMessage(data.message || 'Error starting game');
      }
    } catch (error) {
      console.error('Error starting blackjack game:', error);
      setMessage('Error starting game');
    }
  };

  const hit = async () => {
    if (!currentGame || gameState === 'completed') {
      setMessage('No active game');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/blackjack/${currentGame?.gameId || 'test'}/hit`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      const data = await response.json();

      if (response.ok) {
        if (data.playerHand) setPlayerHand(data.playerHand);
        const playerValue = calculateHandValue(data.playerHand);
        setPlayerValue(playerValue);

        if (data.status === 'completed') {
          setGameState('completed');
          setResult(data.result || 'win');

          if (data.dealerHand) setDealerHand(data.dealerHand);
          const dealerValue = calculateHandValue(data.dealerHand);
          setDealerValue(dealerValue);

          // Update balance based on result
          if (data.result === 'win') {
            setLocalBalance(prev => prev + (betAmount * 2));
          } else if (data.result === 'blackjack') {
            setLocalBalance(prev => prev + (betAmount * 2.5));
          } else if (data.result === 'push') {
            setLocalBalance(prev => prev + betAmount);
          }

          // Trigger final result display after a short delay
          setTimeout(() => {
            setShowFinalResult(true);
          }, 500);
        }
      } else {
        setMessage(data.message || 'Error hitting');
      }
    } catch (error) {
      console.error('Error hitting:', error);
      setMessage('Error hitting');
    }
  };

  const stand = async () => {
    if (!currentGame || gameState === 'completed') {
      setMessage('No active game');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/blackjack/${currentGame?.gameId || 'test'}/stand`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      const data = await response.json();

      if (response.ok) {
        setGameState('completed');
        setResult(data.result || 'win');

        if (data.playerHand) setPlayerHand(data.playerHand);
        if (data.dealerHand) setDealerHand(data.dealerHand);

        const playerValue = calculateHandValue(data.playerHand);
        const dealerValue = calculateHandValue(data.dealerHand);
        setPlayerValue(playerValue);
        setDealerValue(dealerValue);

        // Update balance based on result
        if (data.result === 'win') {
          setLocalBalance(prev => prev + (betAmount * 2));
        } else if (data.result === 'blackjack') {
          setLocalBalance(prev => prev + (betAmount * 2.5));
        } else if (data.result === 'push') {
          setLocalBalance(prev => prev + betAmount);
        }

        // Trigger final result display after a short delay
        setTimeout(() => {
          setShowFinalResult(true);
        }, 500);
      } else {
        setMessage(data.message || 'Error standing');
      }
    } catch (error) {
      console.error('Error standing:', error);
      setMessage('Error standing');
    }
  };

  const resetGame = () => {
    setGameState('waiting');
    setPlayerHand([]);
    setDealerHand([]);
    setPlayerValue(0);
    setDealerValue(0);
    setResult('');
    setMessage('');
    setCurrentGame(null);
    setShowFinalResult(false);
  };

  const adjustBet = (amount) => {
    const newBet = Math.max(10, Math.min(balance, betAmount + amount));
    setBetAmount(newBet);
  };

  return (
    <div className="blackjack-page">
      <div className="card">
        <h2 className="card-title">Blackjack</h2>

        <div className="game-controls">
          <div className="bet-controls">
            <input
              type="number"
              className="form-control"
              placeholder="Bet amount"
              value={betAmount}
              onChange={(e) => setBetAmount(Number(e.target.value))}
              min="10"
              max={balance}
              disabled={gameState !== 'waiting'}
            />
            {gameState === 'waiting' && (
              <button 
                className="btn btn-primary" 
                onClick={startGame}
                disabled={betAmount > balance}
              >
                Deal Cards
              </button>
            )}
          </div>

          <div className="balance-display">
            Balance: {balance?.toLocaleString()} <span className="ampcoin-text">AMP</span>
          </div>
        </div>

        {message && (
          <div className="message">
            <p>{message}</p>
          </div>
        )}

        <div className="game-area">
          <div className="dealer-section">
            <h3>Dealer: {gameState === 'completed' || showFinalResult ? dealerValue : '?'}</h3>
            <div className="cards">
              {dealerHand.map((card, index) => (
                <div key={index} className="card-item">
                  <div className="card-front">
                    {gameState === 'completed' || showFinalResult || index === 0 ? 
                      `${card.rank} of ${card.suit}` : 
                      'Hidden'}
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="player-section">
            <h3>You: {playerValue}</h3>
            <div className="cards">
              {playerHand.map((card, index) => (
                <div key={index} className="card-item">
                  <div className="card-front">
                    {`${card.rank} of ${card.suit}`}
                  </div>
                </div>
              ))}
            </div>

            {gameState === 'in_progress' && (
              <div className="game-buttons">
                <button className="btn btn-primary" onClick={hit}>Hit</button>
                <button className="btn btn-secondary" onClick={stand}>Stand</button>
              </div>
            )}

            {(gameState === 'completed' && showFinalResult) && result && (
              <div className={`result-message ${result}`}>
                <h3>
                  {result === 'win' && 'You Win!'}
                  {result === 'loss' && 'Dealer Wins!'}
                  {result === 'push' && 'Push! (Tie)'}
                  {result === 'blackjack' && 'Blackjack!'}
                </h3>
                {result === 'win' && <p>+{betAmount * 2} AMP</p>}
                {result === 'blackjack' && <p>+{Math.floor(betAmount * 2.5)} AMP</p>}
                {result === 'push' && <p>Bet returned</p>}
                {result !== 'win' && result !== 'push' && result !== 'blackjack' && <p>-{betAmount} AMP</p>}
                <button className="btn btn-primary" onClick={resetGame}>New Game</button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default BlackjackPage;
